 using System.Text.Json;
 using System.Text.Json.Serialization;
 using System.Text.Json.Serialization.Metadata;

 // --- 1) Strongly-typed metadata via cast -----------------------------------
 // Use the reflection-based resolver so GetTypeInfo works for arbitrary types.
 var options = new JsonSerializerOptions(JsonSerializerDefaults.Web)
 {
     TypeInfoResolver = new DefaultJsonTypeInfoResolver()
 };

 JsonTypeInfo<Person> personInfo =
     (JsonTypeInfo<Person>)options.GetTypeInfo(typeof(Person));

 Console.WriteLine($"Type  : {personInfo.Type.Name}");
 Console.WriteLine($"Kind  : {personInfo.Kind}");
 Console.WriteLine($"Props : {string.Join(", ", personInfo.Properties.Select(p => p.Name))}");

 Person original = new("Ada", 38);
 string json = JsonSerializer.Serialize(original, personInfo);
 Person? back = JsonSerializer.Deserialize(json, personInfo);
 Console.WriteLine($"Json  : {json}");
 Console.WriteLine($"Round : {back}");
 Console.WriteLine();

 // --- 2) Probe without throwing ---------------------------------------------
 // A source-gen context only knows about the types you declare.
 var strict = new JsonSerializerOptions { TypeInfoResolver = PersonContext.Default };

 bool havePerson = strict.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? pi);
 bool haveList   = strict.TryGetTypeInfo(typeof(List<int>), out JsonTypeInfo? li);

 Console.WriteLine($"Person available   : {havePerson}  (info null? {pi is null})");
 Console.WriteLine($"List<int> available : {haveList}  (info null? {li is null})");

 // ---------------------------------------------------------------------------
 public record Person(string Name, int Age);

 [JsonSerializable(typeof(Person))]
 public partial class PersonContext : JsonSerializerContext;
